// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address caller, uint128 amount1, uint128 amount2) public {
        vm.assume(caller != address(0));

        vm.deal(caller, uint256(amount1) + uint256(amount2));

        vm.startPrank(caller);
        c.addToBalance{value: amount1}();
        c.withdrawBalance();
        c.addToBalance{value: amount2}();
        vm.stopPrank();

        vm.prank(caller);
        try c.withdrawBalance() {
            assertTrue(true);
        } catch {
            assertTrue(false);
        }
    }
}
